def main():
    argv = sys.argv
    if len(argv) < 2:
        fail(2)
    if argv[1] == "route":
        if len(argv) != 4:
            fail(2)
        file_path, source = argv[2], argv[3]
        nodes, links, node_set = load_network(file_path)
        if source not in node_set:
            fail(5)
        result = compute_routes(nodes, links, source)
    elif argv[1] == "rolepath":
        if len(argv) != 6:
            fail(2)
        file_path, source, destination, limit_text = (
            argv[2], argv[3], argv[4], argv[5])
        names, links, kind_of = load_role_network(file_path)
        if source not in kind_of or destination not in kind_of:
            fail(5)
        if kind_of[source] == "pseudo" or kind_of[destination] == "pseudo":
            fail(5)
        if (not limit_text
                or any(c not in "0123456789" for c in limit_text)):
            fail(5)
        limit_digits = limit_text.lstrip("0") or "0"
        if len(limit_digits) > 10:
            fail(5)
        limit = int(limit_digits)
        if limit > MAX_COST:
            fail(5)
        result = compute_rolepath(names, links, kind_of, source,
                                  destination, limit)
    elif argv[1] == "roletable":
        if len(argv) != 4:
            fail(2)
        file_path, source = argv[2], argv[3]
        names, links, kind_of = load_role_network(file_path)
        if source not in kind_of or kind_of[source] == "pseudo":
            fail(5)
        result = compute_roletable(names, links, kind_of, source)
    elif argv[1] == "ecmp":
        if len(argv) != 5:
            fail(2)
        file_path, source, flow = argv[2], argv[3], argv[4]
        nodes, links, node_set = load_network(file_path)
        if not 1 <= len(flow) <= MAX_FLOW_LEN:
            fail(5)
        try:
            flow.encode("utf-8")
        except UnicodeEncodeError:
            fail(5)
        if source not in node_set:
            fail(5)
        result = compute_ecmp(nodes, links, source, flow)
    elif argv[1] == "metric":
        if len(argv) != 5:
            fail(2)
        file_path, source, order = argv[2], argv[3], argv[4]
        nodes, links, node_set = load_network(file_path, metrics=True)
        order_names = order.split(",")
        if (len(order_names) != 4
                or set(order_names) != {"hop", "cost", "bandwidth", "latency"}
                or len(set(order_names)) != 4):
            fail(5)
        if source not in node_set:
            fail(5)
        result = compute_metric(nodes, links, source, order_names)
    elif argv[1] == "wm":
        if len(argv) != 5:
            fail(2)
        file_path, source, weights_text = argv[2], argv[3], argv[4]
        nodes, links, node_set = load_network(file_path, metrics=True,
                                              strict=True)
        try:
            weights = json.loads(weights_text,
                                 parse_constant=_reject_constant,
                                 parse_float=_finite_float,
                                 object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if (not isinstance(weights, list) or len(weights) != 4
                or any(type(w) is not int or not 0 <= w <= MAX_COST
                       for w in weights)
                or all(w == 0 for w in weights)):
            fail(5)
        if source not in node_set:
            fail(5)
        result = compute_wm(nodes, links, source, weights)
    elif argv[1] == "wmecmp":
        if len(argv) != 6:
            fail(2)
        file_path, source, flow = argv[2], argv[3], argv[4]
        weights_text = argv[5]
        nodes, links, node_set = load_network(file_path, metrics=True,
                                              strict=True)
        try:
            weights = json.loads(weights_text,
                                 parse_constant=_reject_constant,
                                 parse_float=_finite_float,
                                 object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if (not isinstance(weights, list) or len(weights) != 4
                or any(type(w) is not int or not 0 <= w <= MAX_COST
                       for w in weights)
                or all(w == 0 for w in weights)):
            fail(5)
        if not 1 <= len(flow) <= MAX_FLOW_LEN:
            fail(5)
        try:
            flow.encode("utf-8")
        except UnicodeEncodeError:
            fail(5)
        if source not in node_set:
            fail(5)
        result = compute_wmecmp(nodes, links, source, flow, weights)
    elif argv[1] == "wmconverge":
        if len(argv) != 9:
            fail(2)
        file_path, source, destination, weights_text = (
            argv[2], argv[3], argv[4], argv[5])
        delay_text, run_text, events_text = (
            argv[6], argv[7], argv[8])
        nodes, links, node_set = load_network(file_path, metrics=True,
                                              strict=True)
        try:
            weights = json.loads(weights_text,
                                 parse_constant=_reject_constant,
                                 parse_float=_finite_float,
                                 object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if (not isinstance(weights, list) or len(weights) != 4
                or any(type(w) is not int or not 0 <= w <= MAX_COST
                       for w in weights)
                or all(w == 0 for w in weights)):
            fail(5)
        if source not in node_set or destination not in node_set \
                or source == destination:
            fail(5)
        delay = _bounded_int_arg(delay_text)
        run = _bounded_int_arg(run_text)
        try:
            raw_events = json.loads(events_text,
                                   parse_constant=_reject_constant,
                                   parse_float=_finite_float,
                                   object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if not isinstance(raw_events, list) or not raw_events:
            fail(5)
        pair_set = {(link["from"], link["to"]) for link in links}
        events = []
        previous_time = None
        for batch in raw_events:
            if not isinstance(batch, list) or len(batch) != 2:
                fail(5)
            time, changes = batch
            if (type(time) is not int or isinstance(time, bool)
                    or not 0 <= time <= MAX_COST):
                fail(5)
            if previous_time is not None and time <= previous_time:
                fail(5)
            previous_time = time
            if not isinstance(changes, list) or not changes:
                fail(5)
            seen_fields = set()
            parsed_changes = []
            for item in changes:
                if not isinstance(item, list) or len(item) != 4:
                    fail(5)
                kind, frm, to, value = item
                if (type(kind) is not int or isinstance(kind, bool)
                        or not 0 <= kind <= 3):
                    fail(5)
                if (type(frm) is not str or type(to) is not str
                        or (frm, to) not in pair_set):
                    fail(5)
                field_key = (frm, to, kind)
                if field_key in seen_fields:
                    fail(5)
                seen_fields.add(field_key)
                if kind == 3:
                    if type(value) is not bool:
                        fail(5)
                elif kind == 2:
                    if (type(value) is not int or isinstance(value, bool)
                            or not 0 <= value <= MAX_COST):
                        fail(5)
                else:
                    if (type(value) is not int or isinstance(value, bool)
                            or not 1 <= value <= MAX_COST):
                        fail(5)
                parsed_changes.append((kind, frm, to, value))
            events.append((time, parsed_changes))
        result = compute_wmconverge(nodes, links, source, destination,
                                   weights, delay, run, events)
    elif argv[1] == "dispatch":
        if len(argv) != 7:
            fail(2)
        file_path, source, destination, mode, data_text = (
            argv[2], argv[3], argv[4], argv[5], argv[6])
        nodes, links, node_set = load_network(file_path)
        try:
            data = json.loads(data_text, parse_constant=_reject_constant,
                              parse_float=_finite_float,
                              object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if mode not in ("flow", "packet"):
            fail(5)
        if source not in node_set or destination not in node_set \
                or source == destination:
            fail(5)
        if not isinstance(data, list) or not data:
            fail(5)
        packets = []
        seen_ids = set()
        for item in data:
            if not isinstance(item, list) or len(item) != 2:
                fail(5)
            pid, flow = item
            for value in (pid, flow):
                if type(value) is not str \
                        or not 1 <= len(value) <= MAX_FLOW_LEN:
                    fail(5)
                try:
                    value.encode("utf-8")
                except UnicodeEncodeError:
                    fail(5)
            if pid in seen_ids:
                fail(5)
            seen_ids.add(pid)
            packets.append((pid, flow))
        result = compute_dispatch(nodes, links, source, destination,
                                  mode, packets)
    elif argv[1] == "protect":
        if len(argv) != 7:
            fail(2)
        file_path, source, destination = argv[2], argv[3], argv[4]
        delay_text, events_text = argv[5], argv[6]
        nodes, links, node_set = load_network(file_path)
        if (source not in node_set or destination not in node_set
                or source == destination):
            fail(5)
        if (not delay_text
                or any(c not in "0123456789" for c in delay_text)):
            fail(5)
        delay = int(delay_text)
        if delay > MAX_COST:
            fail(5)
        try:
            events = json.loads(events_text, parse_constant=_reject_constant)
        except (ValueError, RecursionError):
            fail(4)
        if not isinstance(events, list):
            fail(5)
        pair_set = {(link["from"], link["to"]) for link in links}
        previous_time = None
        for event in events:
            if (not isinstance(event, dict)
                    or list(event) != ["time", "from", "to", "up"]):
                fail(5)
            time = event["time"]
            frm = event["from"]
            to = event["to"]
            up = event["up"]
            if type(time) is not int or not 0 <= time <= MAX_COST:
                fail(5)
            if previous_time is not None and time < previous_time:
                fail(5)
            previous_time = time
            if (type(frm) is not str or type(to) is not str
                    or (frm, to) not in pair_set):
                fail(5)
            if type(up) is not bool:
                fail(5)
        result = compute_protect(nodes, links, source, destination,
                                 delay, events)
    elif argv[1] == "forward":
        if len(argv) != 7:
            fail(2)
        file_path, source, destination = argv[2], argv[3], argv[4]
        limit_text, table_text = argv[5], argv[6]
        nodes, links, node_set = load_network(file_path, strict=True)
        if source not in node_set or destination not in node_set:
            fail(5)
        if (not limit_text
                or any(c not in "0123456789" for c in limit_text)):
            fail(5)
        # Strip leading zeros before int() so absurdly long digit strings
        # cannot trip Python's integer conversion digit limit.
        limit_digits = limit_text.lstrip("0") or "0"
        if len(limit_digits) > 10:
            fail(5)
        limit = int(limit_digits)
        if limit > MAX_COST:
            fail(5)
        try:
            table = json.loads(table_text, parse_constant=_reject_constant,
                               parse_float=_finite_float,
                               object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if not isinstance(table, dict) or set(table) != node_set:
            fail(5)
        for value in table.values():
            if (value is not None
                    and (type(value) is not str or value not in node_set)):
                fail(5)
        result = compute_forward(links, source, destination, limit, table)
    elif argv[1] == "loopsafe":
        if len(argv) != 5:
            fail(2)
        file_path, destination, table_text = argv[2], argv[3], argv[4]
        nodes, links, node_set = load_network(file_path, strict=True)
        if destination not in node_set:
            fail(5)
        try:
            table = json.loads(table_text, parse_constant=_reject_constant,
                               parse_float=_finite_float,
                               object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if not isinstance(table, dict) or set(table) != node_set:
            fail(5)
        for value in table.values():
            if (value is not None
                    and (type(value) is not str or value not in node_set)):
                fail(5)
        result = compute_loopsafe(links, node_set, destination, table)
    elif argv[1] == "queue":
        if len(argv) != 8:
            fail(2)
        file_path, frm, to = argv[2], argv[3], argv[4]
        cap_text, step_text, data_text = argv[5], argv[6], argv[7]
        nodes, links, node_set = load_network(file_path, strict=True)
        if frm not in node_set or to not in node_set:
            fail(5)
        if not any(link["from"] == frm and link["to"] == to and link["up"]
                   for link in links):
            fail(5)
        cap = _bounded_int_arg(cap_text)
        if cap < 1:
            fail(5)
        step = _bounded_int_arg(step_text)
        if step < 1:
            fail(5)
        try:
            data = json.loads(data_text, parse_constant=_reject_constant,
                              parse_float=_finite_float,
                              object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if not isinstance(data, list):
            fail(5)
        packets = []
        seen_ids = set()
        previous_time = None
        for item in data:
            if (not isinstance(item, dict)
                    or set(item) != {"id", "time", "size"}):
                fail(5)
            pid = item["id"]
            time = item["time"]
            size = item["size"]
            if type(pid) is not str or pid == "" or pid in seen_ids:
                fail(5)
            try:
                pid.encode("utf-8")
            except UnicodeEncodeError:
                fail(5)
            seen_ids.add(pid)
            if type(time) is not int or not 0 <= time <= MAX_COST:
                fail(5)
            if previous_time is not None and time < previous_time:
                fail(5)
            previous_time = time
            if type(size) is not int or not 1 <= size <= MAX_COST:
                fail(5)
            packets.append((pid, time, size))
        result = compute_queue(frm, to, cap, step, packets)
    elif argv[1] == "qdisc":
        if len(argv) != 8:
            fail(2)
        file_path, frm, to = argv[2], argv[3], argv[4]
        step_text, classes_text, data_text = argv[5], argv[6], argv[7]
        nodes, links, node_set = load_network(file_path, strict=True)
        if frm not in node_set or to not in node_set:
            fail(5)
        if not any(link["from"] == frm and link["to"] == to and link["up"]
                   for link in links):
            fail(5)
        step = _bounded_int_arg(step_text)
        if step < 1:
            fail(5)
        try:
            raw_classes = json.loads(classes_text,
                                     parse_constant=_reject_constant,
                                     parse_float=_finite_float,
                                     object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if not isinstance(raw_classes, list) or not raw_classes:
            fail(5)
        classes = []
        seen_names = set()
        for item in raw_classes:
            if not isinstance(item, list) or len(item) != 3:
                fail(5)
            name, quantum, capacity = item
            if type(name) is not str or name == "" or name in seen_names:
                fail(5)
            try:
                name.encode("utf-8")
            except UnicodeEncodeError:
                fail(5)
            seen_names.add(name)
            if type(quantum) is not int or not 1 <= quantum <= MAX_COST:
                fail(5)
            if type(capacity) is not int or not 1 <= capacity <= MAX_COST:
                fail(5)
            classes.append((name, quantum, capacity))
        class_index = {name: i for i, (name, _, _) in enumerate(classes)}
        try:
            data = json.loads(data_text, parse_constant=_reject_constant,
                              parse_float=_finite_float,
                              object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if not isinstance(data, list):
            fail(5)
        packets = []
        seen_ids = set()
        previous_time = None
        for item in data:
            if not isinstance(item, list) or len(item) != 4:
                fail(5)
            pid, time, size, klass = item
            if type(pid) is not str or pid == "" or pid in seen_ids:
                fail(5)
            try:
                pid.encode("utf-8")
            except UnicodeEncodeError:
                fail(5)
            seen_ids.add(pid)
            if type(time) is not int or not 0 <= time <= MAX_COST:
                fail(5)
            if previous_time is not None and time < previous_time:
                fail(5)
            previous_time = time
            if type(size) is not int or not 1 <= size <= MAX_COST:
                fail(5)
            if type(klass) is not str or klass not in class_index:
                fail(5)
            packets.append((pid, time, size, class_index[klass]))
        result = compute_qdisc(frm, to, step, classes, packets)
    elif argv[1] == "fragment":
        if len(argv) != 3:
            fail(2)
        data_text = argv[2]
        try:
            data = json.loads(data_text, parse_constant=_reject_constant,
                              parse_float=_finite_float,
                              object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if not isinstance(data, list) or len(data) != 4:
            fail(5)
        ident, ttl, mtus, hex_text = data
        if type(ident) is not str or not 1 <= len(ident) <= 64:
            fail(5)
        try:
            ident.encode("utf-8")
        except UnicodeEncodeError:
            fail(5)
        if type(ttl) is not int or not 1 <= ttl <= MAX_COST:
            fail(5)
        if not isinstance(mtus, list) or len(mtus) == 0:
            fail(5)
        for mtu in mtus:
            if type(mtu) is not int or not 25 <= mtu <= MAX_COST:
                fail(5)
        if (type(hex_text) is not str or hex_text == ""
                or len(hex_text) % 2 != 0
                or any(ch not in "0123456789abcdef" for ch in hex_text)
                or len(hex_text) // 2 > MAX_COST):
            fail(5)
        payload = bytes.fromhex(hex_text)
        result = compute_fragment(ident, ttl, mtus, payload)
    elif argv[1] == "reassemble":
        if len(argv) != 3:
            fail(2)
        data_text = argv[2]
        try:
            data = json.loads(data_text, parse_constant=_reject_constant,
                              parse_float=_finite_float,
                              object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):
            fail(4)
        if not isinstance(data, list) or len(data) == 0:
            fail(5)
        pieces = []
        expected_offset = 0
        last_index = len(data) - 1
        for index, item in enumerate(data):
            if not isinstance(item, list) or len(item) != 4:
                fail(5)
            offset, more, hex_text, checksum = item
            if type(offset) is not int or not 0 <= offset <= MAX_COST:
                fail(5)
            if type(more) is not bool or more != (index != last_index):
                fail(5)
            if (type(hex_text) is not str or hex_text == ""
                    or len(hex_text) % 2 != 0
                    or any(ch not in "0123456789abcdef" for ch in hex_text)
                    or len(hex_text) // 2 > MAX_COST):
                fail(5)
            if (type(checksum) is not str or len(checksum) != 64
                    or any(ch not in "0123456789abcdef"
                           for ch in checksum)):
                fail(5)
            blob = bytes.fromhex(hex_text)
            if hashlib.sha256(blob).hexdigest() != checksum:
                fail(5)
            # Contiguity check: rejects reordering, overlap, and gaps.
            if offset != expected_offset:
                fail(5)
            expected_offset += len(blob)
            if expected_offset > MAX_COST:
                fail(5)
            pieces.append(blob)
        payload = b"".join(pieces)
        result = {"length": len(payload), "payload": payload.hex()}
    elif argv[1] == "rewrite":
        if len(argv) != 4:
            fail(2)
        r_text, d_text = argv[2], argv[3]
        try:
            rules = json.loads(r_text, parse_constant=_reject_constant,
                               parse_float=_finite_float,
                               object_pairs_hook=_object_no_dup)
        except (ValueError, RecursionError):

elif argv[1] == "netimpair":
    if len(argv) != 6:
        fail(2)
    file_path, queues_text, events_text, data_text = (
        argv[2], argv[3], argv[4], argv[5])
    nodes, links, node_set = load_network(file_path, metrics=True,
                                          strict=True)
    link_pairs_set = {(l["from"], l["to"]) for l in links}
    try:
        raw_queues = json.loads(queues_text,
                                parse_constant=_reject_constant,
                                parse_float=_finite_float,
                                object_pairs_hook=_object_no_dup)
    except (ValueError, RecursionError):
        fail(4)
    if not isinstance(raw_queues, list):
        fail(5)
    cap_of_pair = {}
    for item in raw_queues:
        if not isinstance(item, list) or len(item) != 3:
            fail(5)
        frm, to, capacity = item
        if type(frm) is not str or type(to) is not str:
            fail(5)
        pair = (frm, to)
        if pair not in link_pairs_set or pair in cap_of_pair:
            fail(5)
        if type(capacity) is not int or not 1 <= capacity <= MAX_COST:
            fail(5)
        cap_of_pair[pair] = capacity
    if set(cap_of_pair) != link_pairs_set:
        fail(5)
    cap_of = [cap_of_pair[(l["from"], l["to"])] for l in links]
    latency_of = {(l["from"], l["to"]): l["latency"] for l in links}
    try:
        raw_events = json.loads(events_text,
                                parse_constant=_reject_constant,
                                parse_float=_finite_float,
                                object_pairs_hook=_object_no_dup)
    except (ValueError, RecursionError):
        fail(4)
    # EVENTS is netfail's non-empty, time-ordered array of
    # [t,0,node,up] / [t,1,from,to,up] settings plus
    # [t,2,from,to,n,j] impair settings: n a non-boolean integer in
    # 0..MAX_COST and j a signed integer with latency + j >= 0.
    if not isinstance(raw_events, list) or not raw_events:
        fail(5)
    events = []
    previous_event_time = None
    for event in raw_events:
        if not isinstance(event, list) or len(event) not in (4, 5, 6):
            fail(5)
        t, kind = event[0], event[1]
        if type(t) is not int or not 0 <= t <= MAX_TIME:
            fail(5)
        if previous_event_time is not None and t < previous_event_time:
            fail(5)
        previous_event_time = t
        if type(kind) is not int or kind not in (0, 1, 2):
            fail(5)
        if kind == 0:
            if len(event) != 4:
                fail(5)
            _, _, node, up = event
            if type(node) is not str or node not in node_set:
                fail(5)
            if type(up) is not bool:
                fail(5)
            events.append((t, 0, node, up))
        elif kind == 1:
            if len(event) != 5:
                fail(5)
            _, _, frm, to, up = event
            if (type(frm) is not str or type(to) is not str
                    or (frm, to) not in link_pairs_set):
                fail(5)
            if type(up) is not bool:
                fail(5)
            events.append((t, 1, frm, to, up))
        else:
            if len(event) != 6:
                fail(5)
            _, _, frm, to, nn, jj = event
            if (type(frm) is not str or type(to) is not str
                    or (frm, to) not in link_pairs_set):
                fail(5)
            if type(nn) is not int or not 0 <= nn <= MAX_COST:
                fail(5)
            if type(jj) is not int:
                fail(5)
            if latency_of[(frm, to)] + jj < 0:
                fail(5)
            events.append((t, 2, frm, to, nn, jj))
    try:
